CREATE TABLE IF NOT EXISTS staff_users(id VARCHAR(32) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARBINARY(255) NOT NULL,role VARCHAR(20) NOT NULL,disabled BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS staff_sessions(token_hash CHAR(64) PRIMARY KEY,staff_id VARCHAR(32) NOT NULL,expires_at DATETIME(6) NOT NULL,FOREIGN KEY(staff_id) REFERENCES staff_users(id));
CREATE TABLE IF NOT EXISTS review_assignments(task_id VARCHAR(32) PRIMARY KEY,staff_id VARCHAR(32) NOT NULL,expires_at DATETIME(6) NOT NULL,FOREIGN KEY(task_id) REFERENCES review_tasks(id),FOREIGN KEY(staff_id) REFERENCES staff_users(id));
CREATE TABLE IF NOT EXISTS profile_changes(id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,nickname VARCHAR(40) NOT NULL,bio VARCHAR(300) NOT NULL,avatar_id VARCHAR(32) NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reason VARCHAR(500) NOT NULL DEFAULT '',created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id,created_at));
CREATE TABLE IF NOT EXISTS comment_reports(id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,comment_id VARCHAR(32) NOT NULL,reason VARCHAR(500) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',result VARCHAR(500) NOT NULL DEFAULT '',created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(comment_id) REFERENCES comments(id));
CREATE TABLE IF NOT EXISTS content_disclosures(post_id VARCHAR(32) PRIMARY KEY,is_advertising BOOLEAN NOT NULL DEFAULT FALSE,risk_notes VARCHAR(500) NOT NULL DEFAULT '',reviewed_by VARCHAR(254) NOT NULL,updated_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(post_id) REFERENCES posts(id));
